int list_add(node **head, const char *item_name, float price, int quantity) {
    node *new_node = (node *)malloc(sizeof(node));
    new_node->item_name = strdup(item_name);
    new_node->price = price;
    new_node->quantity = quantity;
    new_node->next = *head;
    *head = new_node;
    return 0;
}

// remove an item from the list
// return 1 if item was removed, 0 if item was not found
int list_remove(node **head, const char *item_name) {
    node *current = *head;
    node *previous = NULL;

    if (*head == NULL) {
        return 0;
    }

    while (current != NULL) {
        if (strcmp(current->item_name, item_name) == 0) {
            if (previous != NULL) {
                previous->next = current->next;
            } else {
                *head = current->next;
            }
            free(current->item_name);
            free(current);
            return 1;
        }
        previous = current;
        current = current->next;
    }
    return 0;
}

