// Replace all spaces in a string with underscores
char *sanitize_name(char *name) {
  int len = strlen(name);
  char *sanitized = (char *)malloc((len + 1) * sizeof(char));
  if (!sanitized)
    display_error("malloc failed");

  for (int i = 0; i < len; ++i) {
    if (name[i] == ' ')
      sanitized[i] = '_';
    else
      sanitized[i] = name[i];
  }
  sanitized[len] = '\0';
  return sanitized;
}

// Check if a string is a valid variable name
int is_valid_name(char *name) {
  int len = strlen(name);
  if (len == 0)
    return 0;

  if (name[0] < 'a' || name[0] > 'z')
    return 0;

  for (int i = 1; i < len; ++i) {
    if (!(name[i] >= 'a' && name[i] <= 'z') && !(name[i] >= '0' && name[i] <= '9') && name[i] != '_')
      return 0;
  }

  return 1;
}

