// Read the input file and store the contents in a buffer
char *read_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        error_log(stderr, "Error opening file.\n");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char *)malloc(size + 1);
    if (!buffer) {
        error_log(stderr, "Error allocating memory.\n");
        fclose(file);
        return NULL;
    }

    size_t read = fread(buffer, 1, size, file);
    if (read != size) {
        error_log(stderr, "Error reading file.\n");
        free(buffer);
        fclose(file);
        return NULL;
    }

    buffer[size] = '\0';
    fclose(file);
    return buffer;
}

