// Read a request from the input stream and store it in a buffer
void read_request(FILE *stream, char *buffer, size_t buffer_size) {
    size_t length = 0;
    size_t bytes_read;

    while (length < buffer_size - 1) {
        bytes_read = fread(&buffer[length], 1, buffer_size - length - 1, stream);
        if (bytes_read == 0) {
            break;
        }
        length += bytes_read;

        // Check for end of request (CR LF)
        if (buffer[length - 2] == '\r' && buffer[length - 1] == '\n') {
            buffer[length] = '\0';
            break;
        }
    }

    // Handle incomplete request
    if (length == 0) {
        fprintf(stderr, "Error: Incomplete request\n");
        exit(1);
    }
}

